let selected='upper',selectedGraphic=null,tab='finish',history=[],future=[],preview=false,flipped=false,zoom=1,reference='ocean',drag=null,pendingBefore=null,savedPalette=null;
const clone=x=>JSON.parse(JSON.stringify(x));
function remember(before=state){history.push(clone(before));if(history.length>60)history.shift();future=[];updateHistory();}
function change(fn){remember();fn();render();}
function updateHistory(){$('undo').disabled=!history.length;$('redo').disabled=!future.length;}
function toast(message){$('toast').textContent=message;$('toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('toast').classList.remove('show'),3000);}
function escapeXML(str){return String(str).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&apos;'}[c]));}
function patternDef(name,id,base,accent,scale=100){const size=24*scale/100;let body='';switch(name){case 'stripes':body=`<path d="M0 0H24V9H0Z" fill="${accent}"/>`;break;case 'checker':body=`<path d="M0 0H12V12H0ZM12 12H24V24H12Z" fill="${accent}"/>`;break;case 'dots':body=`<circle cx="6" cy="6" r="2.4" fill="${accent}"/><circle cx="18" cy="18" r="2.4" fill="${accent}"/>`;break;case 'waves':body=`<path d="M-6 12Q0 0 6 12T18 12T30 12" fill="none" stroke="${accent}" stroke-width="2.3"/>`;break;case 'grid':body=`<path d="M0 0H24M0 0V24M12 0V24M0 12H24" fill="none" stroke="${accent}" stroke-width="1"/>`;break;case 'chevron':body=`<path d="M-6 4L6 16L18 4L30 16M-6 16L6 28L18 16L30 28" fill="none" stroke="${accent}" stroke-width="4"/>`;break;case 'camo':body=`<path d="M0 2Q8-1 12 4T22 4L24 11Q17 17 13 12T0 15Z" fill="${accent}"/><path d="M5 18Q8 13 12 17T20 20L20 24H4Z" fill="${accent}" opacity=".45"/>`;break;case 'speckle':body=`<g fill="${accent}"><circle cx="3" cy="8" r="1"/><circle cx="14" cy="3" r=".8"/><circle cx="20" cy="15" r="1.2"/><circle cx="9" cy="18" r=".7"/><path d="M14 11l2-1 1 2Z"/></g>`;break;case 'diagonal':body=`<path d="M-6 6L6-6M0 24L24 0M18 30L30 18" stroke="${accent}" stroke-width="4"/>`;break;case 'retro':body=`<path d="M0 0H8V24H0Z" fill="${accent}"/><path d="M12 0H15V24H12Z" fill="${accent}" opacity=".55"/>`;break;case 'gradient':return `<linearGradient id="${id}" x1="0" y1="0" x2="1" y2="1"><stop stop-color="${base}"/><stop offset="1" stop-color="${accent}"/></linearGradient>`;default:body='';}return `<pattern id="${id}" width="${size}" height="${size}" patternUnits="userSpaceOnUse"><rect width="${size}" height="${size}" fill="${base}"/><g transform="scale(${scale/100})">${body}</g></pattern>`;}
function materialDef(name,id){let content='';if(name==='mesh')content='<circle cx="3" cy="3" r="1.4" fill="#17201c" opacity=".24"/>';if(name==='canvas')content='<path d="M0 0H8M0 0V8M4 0V8M0 4H8" stroke="#17201c" stroke-width=".55" opacity=".17"/>';if(name==='technical')content='<path d="M0 0L8 8M-4 0L4 8M4 0L12 8" stroke="#fff" stroke-width="1.6" opacity=".28"/>';if(name==='rubber')content='<path d="M0 5H8" stroke="#17201c" stroke-width=".6" opacity=".08"/>';if(name==='suede')content='<circle cx="2" cy="2" r=".65" fill="#fff" opacity=".3"/><circle cx="5" cy="6" r=".65" fill="#000" opacity=".12"/><circle cx="7" cy="3" r=".4" fill="#000" opacity=".18"/>';return `<pattern id="${id}" width="8" height="8" patternUnits="userSpaceOnUse">${content}</pattern>`;}
function zonePath(key,m){return m[key]||'';}
function shoeMarkup(clean=false){if(state.model==='sketch')return sketchMarkup(clean);const m=models[state.model];let defs='<linearGradient id="shade" x1="0" y1="0" x2="0" y2="1"><stop stop-color="#ffffff" stop-opacity=".11"/><stop offset=".6" stop-color="#ffffff" stop-opacity="0"/><stop offset="1" stop-color="#000000" stop-opacity=".07"/></linearGradient>';let parts='';for(const key of ['upper','tongue','heel','side','toe','sole','outsole']){const z=state.zones[key];defs+=patternDef(z.pattern,`pat-${key}`,z.colour,z.accent,z.scale)+materialDef(z.material,`mat-${key}`);const shape=zonePath(key,m);parts+=`<g class="shoe-zone" data-zone="${key}" ${clean?'':`role="button" tabindex="0" aria-label="Edit ${zoneNames[key]}"`}><path d="${shape}" fill="${z.pattern==='none'?z.colour:`url(#pat-${key})`}" stroke="#424b40" stroke-opacity=".6" stroke-width="1.6"/><path d="${shape}" fill="url(#mat-${key})" pointer-events="none"/><path d="${shape}" fill="url(#shade)" pointer-events="none"/>${!clean&&!preview&&selected===key&&!selectedGraphic?`<path d="${shape}" fill="none" stroke="#ed633c" stroke-width="2.5" stroke-dasharray="6 4" pointer-events="none"/>`:''}</g>`;}
defs+=`<clipPath id="shoe-clip"><path d="${m.upper}"/></clipPath>`;
let details=`<path d="${m.collar}" fill="none" stroke="#323a31" stroke-width="8" stroke-linecap="round" opacity=".28"/><path d="${m.side}" fill="none" stroke="#fff" stroke-opacity=".45" stroke-width="1.1" stroke-dasharray="3 4" transform="translate(2 -4)"/><path d="M128 382Q358 398 763 376" fill="none" stroke="#555e4d" stroke-width="1" opacity=".25"/>`;
if(m.toeDots)for(let x=595;x<720;x+=19)for(let y=320;y<344;y+=12)details+=`<circle cx="${x}" cy="${y}" r="1.6" fill="#293526" opacity=".25"/>`;
if(state.model==='runner')details+='<path d="M223 278L249 360M254 265L279 360M285 249L308 363" stroke="#faffed" stroke-width="6" opacity=".3" fill="none"/>';
details+=m.eyelets.map(([x,y])=>`<circle cx="${x}" cy="${y}" r="4.8" fill="#26312a" opacity=".35"/><circle cx="${x}" cy="${y}" r="2" fill="#171d17" opacity=".5"/>`).join('');
const lace=state.zones.laces;details+=`<g class="shoe-zone" data-zone="laces" ${clean?'':`role="button" tabindex="0" aria-label="Edit laces"`}><path d="${m.laces}" fill="none" stroke="#293526" stroke-width="9" opacity=".16" stroke-linecap="round"/><path d="${m.laces}" fill="none" stroke="${lace.colour}" stroke-width="6.3" stroke-linecap="round"/>${!clean&&!preview&&selected==='laces'&&!selectedGraphic?`<path d="${m.laces}" stroke="#ed633c" stroke-width="2" fill="none"/>`:''}</g>`;
const graphics=state.graphics.map(g=>{const transform=`translate(${g.x} ${g.y}) rotate(${g.rotation}) scale(${g.mirror?-1:1} 1)`;const art=g.type==='text'?`<text text-anchor="middle" dominant-baseline="middle" font-family="Arial,sans-serif" font-weight="700" font-size="${g.size/Math.max(3,g.text.length*.64)}" fill="${g.colour}">${escapeXML(g.text)}</text>`:`<image href="${g.data}" x="${-g.size/2}" y="${-g.size*g.ratio/2}" width="${g.size}" height="${g.size*g.ratio}"/>`;return `<g class="graphic" data-graphic="${g.id}" transform="${transform}" ${clean?'':`role="button" tabindex="0" aria-label="Select ${escapeXML(g.label)}"`}>${art}${!clean&&!preview&&selectedGraphic===g.id?`<rect x="${-g.size/2-5}" y="${-(g.type==='text'?g.size/3:g.size*g.ratio)/2-5}" width="${g.size+10}" height="${(g.type==='text'?g.size/3:g.size*g.ratio)+10}" fill="transparent" stroke="#ed633c" stroke-width="1.5" stroke-dasharray="5 3"/>`:''}</g>`}).join('');
const view=clean?'':`translate(450 270) scale(${zoom*(flipped?-1:1)} ${zoom}) translate(-450 -270)`;
return `<defs>${defs}</defs>${!clean?'<ellipse cx="450" cy="432" rx="305" ry="14" fill="#72805b" opacity=".1"/>':''}<g transform="${view}">${parts}${details}<g clip-path="url(#shoe-clip)">${graphics}</g></g>`;
}
function sketchMarkup(clean=false){
 let defs='<clipPath id="sketch-clip"><path d="'+sketchGeometry.upper+'"/></clipPath>',panels='';
 for(const key of ['upper','tongue','heel','side','toe','sole','outsole','laces']){const z=state.zones[key];defs+=patternDef(z.pattern,'sketch-pat-'+key,z.colour,z.accent,z.scale)+materialDef(z.material,'sketch-mat-'+key);panels+=`<g class="shoe-zone" data-zone="${key}" ${clean?'':`role="button" tabindex="0" aria-label="Edit ${zoneNames[key]}"`}><path d="${sketchGeometry[key]}" fill="${z.pattern==='none'?z.colour:`url(#sketch-pat-${key})`}"/><path d="${sketchGeometry[key]}" fill="url(#sketch-mat-${key})" pointer-events="none"/></g>`;}
 const graphics=state.graphics.map(g=>{const art=g.type==='text'?`<text text-anchor="middle" dominant-baseline="middle" font-family="Arial,sans-serif" font-weight="700" font-size="${g.size/Math.max(3,g.text.length*.64)}" fill="${g.colour}">${escapeXML(g.text)}</text>`:`<image href="${g.data}" x="${-g.size/2}" y="${-g.size*g.ratio/2}" width="${g.size}" height="${g.size*g.ratio}"/>`;return `<g class="graphic" data-graphic="${g.id}" transform="translate(${g.x} ${g.y}) rotate(${g.rotation}) scale(${g.mirror?-1:1} 1)" ${clean?'':`role="button" tabindex="0" aria-label="Select ${escapeXML(g.label)}"`}>${art}${!clean&&!preview&&selectedGraphic===g.id?`<rect x="${-g.size/2-5}" y="${-(g.type==='text'?g.size/3:g.size*g.ratio)/2-5}" width="${g.size+10}" height="${(g.type==='text'?g.size/3:g.size*g.ratio)+10}" fill="transparent" stroke="#ed633c" stroke-width="1.5" stroke-dasharray="5 3"/>`:''}</g>`;}).join('');
 const selection=!clean&&!preview&&!selectedGraphic?`<path d="${sketchGeometry[selected]}" fill="none" stroke="#ed633c" stroke-width="2" stroke-dasharray="5 4" pointer-events="none"/>`:'';
 const view=clean?'':`translate(450 470) scale(${zoom*(flipped?-1:1)} ${zoom}) translate(-450 -470)`;
 return `<defs>${defs}</defs><g transform="${view}">${panels}<g clip-path="url(#sketch-clip)">${graphics}</g><image href="${sketchInk}" width="900" height="900" pointer-events="none"/>${selection}</g>`;
}
function renderShoe(){$('shoe').setAttribute('viewBox',state.model==='sketch'?'0 90 900 760':'0 0 900 510');$('shoe').innerHTML=shoeMarkup();}
function setTab(next){tab=next;document.querySelectorAll('[data-tab]').forEach(b=>{b.classList.toggle('active',b.dataset.tab===tab);b.setAttribute('aria-selected',String(b.dataset.tab===tab));});for(const t of ['finish','graphics','layers'])$(t+'-panel').hidden=t!==tab;}
function syncControls(){const z=state.zones[selected];$('edit-heading').textContent=selectedGraphic?'Artwork':zoneNames[selected];$('edit-subtitle').textContent=selectedGraphic?'Position your own mark.':'Give this panel its own character.';$('colour').value=z.colour;$('hex').value=z.colour;$('accent').value=z.accent;$('pattern-scale').value=z.scale;$('scale-caption').textContent=z.scale+'%';$('material').value=z.material;document.querySelectorAll('.pattern').forEach(b=>b.classList.toggle('active',b.dataset.pattern===z.pattern));document.querySelectorAll('.swatch[data-colour]').forEach(b=>b.classList.toggle('active',b.dataset.colour===z.colour));$('graphic-y').max=state.model==='sketch'?780:380;const isLaces=selected==='laces'&&state.model!=='sketch';$('patterns').querySelectorAll('button').forEach(b=>b.disabled=isLaces);$('accent').disabled=isLaces;$('pattern-scale').disabled=isLaces;$('material').disabled=isLaces;const g=state.graphics.find(g=>g.id===selectedGraphic);$('graphic-controls').hidden=!g;if(g){$('graphic-colour').value=g.colour||'#252e2b';$('graphic-colour').disabled=g.type!=='text';$('graphic-size').value=g.size;$('graphic-rotate').value=g.rotation;$('graphic-x').value=Math.round(g.x);$('graphic-y').value=Math.round(g.y);}}
function render(){queueDraftSave();renderShoe();$('zones').innerHTML=Object.entries(zoneNames).map(([key,label])=>`<button class="zone-button ${selected===key&&!selectedGraphic?'active':''}" data-zone="${key}"><span style="background:${state.zones[key].colour}"></span>${label}<span class="zone-end">${selected===key&&!selectedGraphic?'●':'+'}</span></button>`).join('');$('templates').innerHTML=Object.entries(models).filter(([key])=>key==='sketch').map(([key,m])=>`<button class="template ${state.model===key?'active':''}" data-model="${key}" title="${m.description}"><svg viewBox="0 0 900 900" aria-hidden="true"><path d="${sketchGeometry.upper}" fill="${state.model===key?'#dfff73':'#dce1d4'}" stroke="#343d30" stroke-width="10"/><path d="${sketchGeometry.sole}" fill="#fafbf6" stroke="#343d30" stroke-width="8"/><path d="${sketchGeometry.laces}" stroke="#343d30" stroke-width="10"/></svg><span>${m.label}</span></button>`).join('');$('canvas-name').textContent=state.name;$('design-name').value=state.name;$('model-label').textContent=models[state.model].label.toUpperCase();$('selected-caption').textContent=preview?'Presentation preview':selectedGraphic?'Artwork selected':zoneNames[selected]+' selected';$('canvas-hint').textContent=preview?'Your design, ready to present':selectedGraphic?'Drag your artwork to position it':'Select a shoe panel to begin';$('canvas-mode').textContent=preview?'PREVIEW':'EDITABLE';$('canvas').classList.toggle('preview-mode',preview);$('design-view').classList.toggle('active',!preview);$('preview-view').classList.toggle('active',preview);$('zoom-label').textContent=Math.round(zoom*100)+'%';$('colourway').innerHTML=[...new Set(Object.values(state.zones).map(z=>z.colour))].map(c=>`<button title="Use ${c} on selected panel" aria-label="Use colour ${c}" style="background:${c}" data-colourway="${c}"></button>`).join('');$('layers').innerHTML=state.graphics.length?state.graphics.slice().reverse().map(g=>`<button class="layer ${selectedGraphic===g.id?'active':''}" data-layer="${g.id}"><span>${g.type==='text'?'T':'▧'}</span><span>${escapeXML(g.label)}</span></button>`).join(''):'<p class="note">No artwork yet. Add text or upload a graphic in the Graphics tab.</p>';$('layer-up').disabled=!selectedGraphic||state.graphics.at(-1)?.id===selectedGraphic;$('layer-down').disabled=!selectedGraphic||state.graphics[0]?.id===selectedGraphic;syncControls();updateHistory();if(state.inspiration){$('inspiration-strip').innerHTML=`<span>✧</span><p>INSPIRED BY / ${refs[state.inspiration].label.toUpperCase()}<br><strong>${refs[state.inspiration].title}</strong></p><button id="explore">View references</button>`;}else{$('inspiration-strip').innerHTML='<span>✧</span><p>Your next idea could come from anywhere.<br><strong>Find inspiration beyond footwear.</strong></p><button id="explore">Explore references</button>';}}
function selectZone(key){if(!zoneNames[key])return;selected=key;selectedGraphic=null;preview=false;setTab('finish');render();}
function selectGraphic(id){if(!state.graphics.some(g=>g.id===id))return;selectedGraphic=id;preview=false;setTab('graphics');render();}
function applyPanel(property,value){change(()=>{state.zones[selected][property]=value;});}
function liveInput(element,apply){element.addEventListener('input',()=>{if(!pendingBefore)pendingBefore=clone(state);apply(element.value);renderShoe();syncColourway();});element.addEventListener('change',()=>{if(pendingBefore){remember(pendingBefore);pendingBefore=null;}render();});}
function syncColourway(){const z=state.zones[selected];$('hex').value=z.colour;$('scale-caption').textContent=z.scale+'%';}
$('patterns').innerHTML=Object.entries(patternNames).map(([name,label],i)=>`<button class="pattern" data-pattern="${name}" aria-label="${label} pattern"><svg viewBox="0 0 72 30" aria-hidden="true"><defs>${patternDef(name,'sample-'+i,'#ecf0e1','#657755',70)}</defs><rect width="72" height="30" fill="url(#sample-${i})"/></svg><span>${label}</span></button>`).join('');
$('swatches').innerHTML=colours.map(c=>`<button class="swatch" style="background:${c}" data-colour="${c}" aria-label="Panel colour ${c}" title="${c}"></button>`).join('');
$('zones').addEventListener('click',e=>{const b=e.target.closest('[data-zone]');if(b)selectZone(b.dataset.zone);});
$('templates').addEventListener('click',e=>{const b=e.target.closest('[data-model]');if(b)change(()=>{state.model=b.dataset.model;});});
document.querySelectorAll('[data-tab]').forEach(b=>b.addEventListener('click',()=>setTab(b.dataset.tab)));
$('swatches').addEventListener('click',e=>{const b=e.target.closest('[data-colour]');if(b)applyPanel('colour',b.dataset.colour);});
$('colourway').addEventListener('click',e=>{const b=e.target.closest('[data-colourway]');if(b)applyPanel('colour',b.dataset.colourway);});
$('patterns').addEventListener('click',e=>{const b=e.target.closest('[data-pattern]');if(b){if(selected==='laces'&&state.model!=='sketch'){toast('Laces support colour changes. Select a fabric panel for patterns.');return;}applyPanel('pattern',b.dataset.pattern);}});
liveInput($('colour'),v=>state.zones[selected].colour=v);liveInput($('accent'),v=>state.zones[selected].accent=v);liveInput($('pattern-scale'),v=>state.zones[selected].scale=Number(v));
$('hex').addEventListener('change',()=>{let value=$('hex').value;if(!value.startsWith('#'))value='#'+value;if(/^#[0-9a-f]{6}$/i.test(value))applyPanel('colour',value.toLowerCase());else{toast('Enter a six-digit hex colour, such as #DFFF73.');syncControls();}});
$('material').addEventListener('change',()=>{if(selected==='laces'&&state.model!=='sketch'){toast('Laces support colour changes. Choose another panel for materials.');syncControls();return;}applyPanel('material',$('material').value);});
$('design-name').addEventListener('change',()=>change(()=>state.name=$('design-name').value.trim()||'Untitled colourway'));
$('undo').addEventListener('click',()=>{if(!history.length)return;future.push(clone(state));state=history.pop();if(!state.graphics.some(g=>g.id===selectedGraphic))selectedGraphic=null;render();});
$('redo').addEventListener('click',()=>{if(!future.length)return;history.push(clone(state));state=future.pop();if(!state.graphics.some(g=>g.id===selectedGraphic))selectedGraphic=null;render();});
document.addEventListener('keydown',e=>{if(e.target.matches('input,textarea,select'))return;if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='z'){e.preventDefault();$(e.shiftKey?'redo':'undo').click();}if((e.key==='Delete'||e.key==='Backspace')&&selectedGraphic){e.preventDefault();$('delete-graphic').click();}});
$('design-view').onclick=()=>{preview=false;render();};$('preview-view').onclick=()=>{preview=true;render();};$('flip').onclick=()=>{flipped=!flipped;renderShoe();};$('zoom-in').onclick=()=>{zoom=Math.min(1.25,zoom+.1);render();};$('zoom-out').onclick=()=>{zoom=Math.max(.65,zoom-.1);render();};
$('save-palette').onclick=()=>{savedPalette=[...new Set(Object.values(state.zones).map(z=>z.colour))];$('load-palette').hidden=false;queueDraftSave();toast('Palette saved on this device.');};
$('load-palette').onclick=()=>{$('swatches').innerHTML=[...new Set([...savedPalette,...colours])].map(c=>`<button class="swatch" style="background:${c}" data-colour="${c}" aria-label="Panel colour ${c}" title="${c}"></button>`).join('');syncControls();toast('Saved colours added to your swatches.');};
function newGraphicId(){return 'g'+Date.now().toString(36)+Math.random().toString(36).slice(2,7);}
$('add-text').onclick=()=>{const text=$('text-input').value.trim();if(!text){toast('Write a name or message first.');$('text-input').focus();return;}const id=newGraphicId();change(()=>state.graphics.push({id,type:'text',label:text,text,x:state.model==='sketch'?420:390,y:state.model==='sketch'?440:323,size:Math.max(80,Math.min(230,text.length*12)),rotation:0,mirror:false,colour:'#252e2b'}));selectedGraphic=id;setTab('graphics');render();};
$('upload').addEventListener('change',async()=>{const file=$('upload').files[0];if(!file)return;if(file.size>5*1024*1024){toast('Choose an image smaller than 5 MB.');$('upload').value='';return;}if(!['image/png','image/jpeg','image/webp'].includes(file.type)){toast('Choose a PNG, JPG or WebP image.');$('upload').value='';return;}try{const data=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=reject;reader.readAsDataURL(file);});const image=new Image();image.src=data;await image.decode();const canvas=document.createElement('canvas');const factor=Math.min(1,1200/Math.max(image.width,image.height));canvas.width=Math.round(image.width*factor);canvas.height=Math.round(image.height*factor);canvas.getContext('2d').drawImage(image,0,0,canvas.width,canvas.height);const id=newGraphicId();change(()=>state.graphics.push({id,type:'image',label:file.name,data:canvas.toDataURL('image/png'),ratio:image.height/image.width,x:state.model==='sketch'?420:390,y:state.model==='sketch'?440:320,size:120,rotation:0,mirror:false}));selectedGraphic=id;setTab('graphics');render();toast('Artwork added. Drag it to position it.');}catch{toast('That image could not be opened. Try another file.');}finally{$('upload').value='';}});
for(const [id,property] of [['graphic-colour','colour'],['graphic-size','size'],['graphic-rotate','rotation'],['graphic-x','x'],['graphic-y','y']])liveInput($(id),v=>{const g=state.graphics.find(g=>g.id===selectedGraphic);if(g)g[property]=property==='colour'?v:Math.max(property==='x'?80:property==='y'?110:property==='size'?20:-180,Math.min(property==='x'?820:property==='y'?(state.model==='sketch'?780:380):property==='size'?280:180,Number(v)));});
$('mirror-graphic').onclick=()=>change(()=>{const g=state.graphics.find(g=>g.id===selectedGraphic);if(g)g.mirror=!g.mirror;});
$('delete-graphic').onclick=()=>{if(!selectedGraphic)return;change(()=>{state.graphics=state.graphics.filter(g=>g.id!==selectedGraphic);selectedGraphic=null;});};
$('layers').onclick=e=>{const b=e.target.closest('[data-layer]');if(b)selectGraphic(b.dataset.layer);};
function reorder(direction){const i=state.graphics.findIndex(g=>g.id===selectedGraphic);const j=i+direction;if(i<0||j<0||j>=state.graphics.length)return;change(()=>{[state.graphics[i],state.graphics[j]]=[state.graphics[j],state.graphics[i]];});}
$('layer-up').onclick=()=>reorder(1);$('layer-down').onclick=()=>reorder(-1);
function canvasPoint(e){const p=$('shoe').createSVGPoint();p.x=e.clientX;p.y=e.clientY;const raw=p.matrixTransform($('shoe').getScreenCTM().inverse());const cy=state.model==='sketch'?470:270;return{x:450+(raw.x-450)/(zoom*(flipped?-1:1)),y:cy+(raw.y-cy)/zoom};}
$('shoe').addEventListener('pointerdown',e=>{if(preview)return;const target=e.target.closest('[data-graphic]');if(target){e.preventDefault();const id=target.dataset.graphic;selectGraphic(id);const g=state.graphics.find(g=>g.id===id);const p=canvasPoint(e);drag={id,dx:g.x-p.x,dy:g.y-p.y,before:clone(state),moved:false};$('shoe').setPointerCapture(e.pointerId);}else{const z=e.target.closest('[data-zone]');if(z)selectZone(z.dataset.zone);}});
$('shoe').addEventListener('pointermove',e=>{if(!drag)return;const p=canvasPoint(e);const g=state.graphics.find(g=>g.id===drag.id);g.x=Math.max(100,Math.min(790,p.x+drag.dx));g.y=Math.max(135,Math.min(state.model==='sketch'?780:375,p.y+drag.dy));drag.moved=true;renderShoe();$('graphic-x').value=Math.round(g.x);$('graphic-y').value=Math.round(g.y);});
function endDrag(){if(drag){if(drag.moved)remember(drag.before);drag=null;render();}}
$('shoe').addEventListener('pointerup',endDrag);$('shoe').addEventListener('pointercancel',endDrag);
$('shoe').addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){const z=e.target.closest('[data-zone]');const g=e.target.closest('[data-graphic]');if(z||g)e.preventDefault();if(g)selectGraphic(g.dataset.graphic);else if(z)selectZone(z.dataset.zone);}});
function renderReference(){$('territories').innerHTML=Object.entries(refs).map(([id,r])=>`<button class="${reference===id?'active':''}" data-ref="${id}">${r.label}</button>`).join('');const r=refs[reference];$('reference-content').innerHTML=`<div class="reference-grid"><div>${r.image?`<img class="reference-photo" src="${r.image}" alt="${r.alt}" loading="lazy" referrerpolicy="no-referrer">`:`<div class="reference-art">${reference==='nouveau'?'Art Nouveau':'Art Deco'}<br>V&A Collections</div>`}<div class="reference-credit">${r.credit}</div><div class="reference-links">${r.links.map(([name,url])=>`<a href="${url}" target="_blank" rel="noopener noreferrer">${name} ↗</a>`).join('')}</div><p class="note">References are for research. Check each source’s rights before reusing its imagery.</p></div><div><h3>${r.title}</h3><p>${r.story}</p><span class="eyebrow">A POSSIBLE STARTING PALETTE</span><div class="swatches">${r.palette.map(c=>`<button class="swatch" style="background:${c}" data-reference-colour="${c}" aria-label="Apply ${c} to selected panel" title="Apply to selected panel"></button>`).join('')}</div><div class="suggestion">${r.idea}</div><div class="reference-apply"><button id="try-pattern">Try ${patternNames[r.pattern].toLowerCase()} on this panel</button><button id="try-material">Try ${r.material} finish</button></div><button id="use-reference" class="primary">Use this inspiration</button><p class="note">Adds palette suggestions. You decide which colours, patterns and finishes to use.</p></div></div>`;$('try-pattern').onclick=()=>{if(selected==='laces'&&state.model!=='sketch'){toast('Choose a fabric panel first.');return;}applyPanel('pattern',r.pattern);toast(patternNames[r.pattern]+' applied to '+zoneNames[selected].toLowerCase()+'.');};$('try-material').onclick=()=>{if(selected==='laces'&&state.model!=='sketch'){toast('Choose a fabric panel first.');return;}applyPanel('material',r.material);toast('Material applied to '+zoneNames[selected].toLowerCase()+'.');};const photo=$('reference-content').querySelector('img');if(photo)photo.onerror=()=>{photo.hidden=true;photo.insertAdjacentHTML('afterend','<p class="note">Open the source link below to view the reference image.</p>');};$('use-reference').onclick=()=>{change(()=>state.inspiration=reference);const palette=refs[reference].palette;$('swatches').innerHTML=[...new Set([...palette,...colours])].map(c=>`<button class="swatch" style="background:${c}" data-colour="${c}" aria-label="Panel colour ${c}" title="${c}"></button>`).join('');syncControls();$('inspiration-dialog').close();toast('Inspiration saved. Try the suggested colours on your panels.');};}
function openInspiration(){if(state.inspiration)reference=state.inspiration;renderReference();$('inspiration-dialog').showModal();}
$('inspire').onclick=openInspiration;$('inspiration-strip').onclick=e=>{if(e.target.closest('button'))openInspiration();};
$('territories').onclick=e=>{const b=e.target.closest('[data-ref]');if(b){reference=b.dataset.ref;renderReference();}};
$('reference-content').onclick=e=>{const b=e.target.closest('[data-reference-colour]');if(b){applyPanel('colour',b.dataset.referenceColour);toast('Colour applied to '+zoneNames[selected].toLowerCase()+'.');}};
document.querySelectorAll('.close-dialog').forEach(b=>b.onclick=()=>b.closest('dialog').close());document.querySelectorAll('dialog').forEach(d=>d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close();}}));
$('export').onclick=()=>$('export-dialog').showModal();
function svgString(){return `<svg xmlns="http://www.w3.org/2000/svg" width="1800" height="${state.model==='sketch'?1520:1020}" viewBox="${state.model==='sketch'?'0 90 900 760':'0 0 900 510'}"><title>${escapeXML(state.name)}</title>${shoeMarkup(true)}</svg>`;}
function downloadBlob(blob,suffix){const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=(state.name.replace(/[^a-z0-9_-]/gi,'-')||'sneaker')+suffix;a.click();setTimeout(()=>URL.revokeObjectURL(url),5000);}
async function renderImage(){const url=URL.createObjectURL(new Blob([svgString()],{type:'image/svg+xml'}));try{const img=new Image();img.src=url;await img.decode();return img;}finally{URL.revokeObjectURL(url);}}
async function pngExport(board=false){try{const img=await renderImage();const c=document.createElement('canvas');c.width=1800;c.height=board?1450:img.height;const ctx=c.getContext('2d');if(board){ctx.fillStyle='#f3f6ec';ctx.fillRect(0,0,c.width,c.height);ctx.fillStyle='#252e2b';ctx.font='bold 26px Arial';ctx.fillText('DESIGNXDM / SNEAKER STUDIO',100,90);ctx.font='bold 52px Arial';ctx.fillText(state.name,100,175);ctx.font='23px Arial';ctx.fillStyle='#68755d';ctx.fillText('MY INSPIRATION  /  MY COLOUR PALETTE  /  MY SNEAKER',100,230);ctx.drawImage(img,260,245,1280,Math.min(1000,1280*img.height/img.width));ctx.fillStyle='#252e2b';ctx.font='bold 23px Arial';ctx.fillText('COLOURWAY',100,1190);const palette=[...new Set(Object.values(state.zones).map(z=>z.colour))];palette.forEach((colour,i)=>{ctx.fillStyle=colour;ctx.fillRect(100+i*100,1210,78,52);ctx.fillStyle='#68755d';ctx.font='16px Arial';ctx.fillText(colour.toUpperCase(),100+i*100,1285);});ctx.fillStyle='#252e2b';ctx.font='22px Arial';const r=state.inspiration&&refs[state.inspiration];ctx.fillText(r?'INSPIRED BY / '+r.label.toUpperCase():'MY INSPIRATION / Add your own reference story',100,1350);ctx.font='16px Arial';ctx.fillStyle='#68755d';if(r){ctx.fillText(r.credit,100,1385);ctx.fillText(r.links[0][1],100,1415);}}else ctx.drawImage(img,0,0,1800,img.height);const blob=await new Promise(resolve=>c.toBlob(resolve,'image/png'));if(!blob)throw Error('PNG encoding failed');downloadBlob(blob,board?'-design-board.png':'.png');toast(board?'Presentation board downloaded.':'Transparent PNG downloaded.');}catch{toast('Export could not finish. Try downloading the SVG instead.');}}
$('download-png').onclick=()=>pngExport();$('download-board').onclick=()=>pngExport(true);$('download-svg').onclick=()=>{downloadBlob(new Blob([svgString()],{type:'image/svg+xml'}),'.svg');toast('Editable vector downloaded.');};
if(document.modelContext?.registerTool){try{const lifecycle=new AbortController();Promise.resolve(document.modelContext.registerTool({name:'read_sneaker_design',title:'Read sneaker design',description:'Read the current sneaker template, panel treatments and artwork count.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute(){return {name:state.name,template:state.model,panels:clone(state.zones),artworkCount:state.graphics.length,inspiration:state.inspiration};}},{signal:lifecycle.signal})).catch(()=>{});Promise.resolve(document.modelContext.registerTool({name:'set_sneaker_panel_colours',title:'Set panel colours',description:'Apply hex colours to a batch of sneaker panels, preserving all other design choices.',inputSchema:{type:'object',properties:{colours:{type:'object',properties:Object.fromEntries(Object.keys(zoneNames).map(k=>[k,{type:'string',pattern:'^#[0-9a-fA-F]{6}$'}])),additionalProperties:false}},required:['colours'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(input){if(!input||Object.keys(input).some(k=>k!=='colours')||!input.colours||typeof input.colours!=='object'||Array.isArray(input.colours))throw Error('Supply a colours object.');for(const [key,value]of Object.entries(input.colours))if(!zoneNames[key]||typeof value!=='string'||!/^#[0-9a-f]{6}$/i.test(value))throw Error('Unknown panel or invalid hex colour.');change(()=>{for(const [key,value]of Object.entries(input.colours))state.zones[key].colour=value.toLowerCase();});return {updatedPanels:Object.keys(input.colours)};}},{signal:lifecycle.signal})).catch(()=>{});window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});}catch{}}
const draftKey='designxdm-sneaker-draft-v1';
const paletteKey='designxdm-sneaker-palette-v1';
let draftTimer=null;
function validHex(value){return typeof value==='string'&&/^#[0-9a-f]{6}$/i.test(value);}
function validateProject(raw){
 if(!raw||raw.format!=='designxdm-sneaker'||raw.version!==1||!raw.design)throw Error('Choose a DesignXDM sneaker project file.');
 const d=raw.design;if(!Object.hasOwn(models,d.model)||typeof d.name!=='string'||d.name.length>45||!d.zones||!Array.isArray(d.graphics)||d.graphics.length>50)throw Error('Invalid project structure.');
 const clean={model:d.model,name:d.name.trim()||'Untitled colourway',zones:{},graphics:[],inspiration:d.inspiration===null?null:Object.hasOwn(refs,d.inspiration)?d.inspiration:null};
 for(const key of Object.keys(zoneNames)){const z=d.zones[key];if(!z||!validHex(z.colour)||!validHex(z.accent)||!Object.hasOwn(patternNames,z.pattern)||!['smooth','suede','mesh','canvas','rubber','technical'].includes(z.material)||!Number.isFinite(z.scale)||z.scale<40||z.scale>180)throw Error('Invalid panel settings.');clean.zones[key]={colour:z.colour,accent:z.accent,pattern:z.pattern,scale:z.scale,material:z.material};}
 const ids=new Set();for(const g of d.graphics){if(!g||!['text','image'].includes(g.type)||typeof g.id!=='string'||!/^g[a-z0-9]{1,60}$/i.test(g.id)||ids.has(g.id)||typeof g.label!=='string'||g.label.length>255||!Number.isFinite(g.x)||g.x<80||g.x>820||!Number.isFinite(g.y)||g.y<110||g.y>780||!Number.isFinite(g.size)||g.size<20||g.size>280||!Number.isFinite(g.rotation)||Math.abs(g.rotation)>180||typeof g.mirror!=='boolean')throw Error('Invalid artwork layer.');ids.add(g.id);const c={id:g.id,type:g.type,label:g.label,x:g.x,y:g.y,size:g.size,rotation:g.rotation,mirror:g.mirror};if(g.type==='text'){if(typeof g.text!=='string'||g.text.length>30||!validHex(g.colour))throw Error('Invalid text layer.');Object.assign(c,{text:g.text,colour:g.colour});}else{if(typeof g.data!=='string'||g.data.length>8000000||!/^data:image\/png;base64,[A-Za-z0-9+/]+={0,2}$/.test(g.data)||!Number.isFinite(g.ratio)||g.ratio<.01||g.ratio>100)throw Error('Invalid uploaded image.');Object.assign(c,{data:g.data,ratio:g.ratio});}clean.graphics.push(c);}
 return clean;
}
function upgradeSketchDesign(design){if(design.model!=='sketch'){design.model='sketch';for(const g of design.graphics){g.x=Math.min(820,Math.max(80,g.x+30));g.y=Math.min(780,Math.max(110,g.y+120));}}return design;}
function projectData(){return{format:'designxdm-sneaker',version:1,design:state};}
function queueDraftSave(){clearTimeout(draftTimer);draftTimer=setTimeout(saveDraft,450);}
function saveDraft(){try{localStorage.setItem(draftKey,JSON.stringify(projectData()));if(savedPalette)localStorage.setItem(paletteKey,JSON.stringify(savedPalette));$('save-status').textContent='Saved on this device.';}catch{$('save-status').textContent='Device storage is full or unavailable. Use Save project to keep your design.';}}
function restoreDraft(){try{const data=localStorage.getItem(draftKey);if(data)state=upgradeSketchDesign(validateProject(JSON.parse(data)));const palette=JSON.parse(localStorage.getItem(paletteKey)||'null');if(Array.isArray(palette)&&palette.length<=30&&palette.every(validHex)){savedPalette=palette;$('load-palette').hidden=false;}}catch{$('save-status').textContent='Previous draft could not be opened. Your project files can still be imported.';}}
$('save-project').onclick=()=>{downloadBlob(new Blob([JSON.stringify(projectData(),null,2)],{type:'application/json'}),'.sneaker.json');toast('Project downloaded. Use Open to edit it again.');};
$('open-project').onclick=()=>$('project-file').click();
$('project-file').addEventListener('change',async()=>{const file=$('project-file').files[0];if(!file)return;try{if(file.size>20000000)throw Error('Choose a project smaller than 20 MB.');const next=upgradeSketchDesign(validateProject(JSON.parse(await file.text())));change(()=>{state=next;selectedGraphic=null;preview=false;zoom=1;flipped=false;});toast('Project opened. Undo returns to your previous design.');}catch(error){toast(error instanceof SyntaxError?'That file is not valid JSON.':error.message||'That project could not be opened.');}finally{$('project-file').value='';}});
window.addEventListener('pagehide',saveDraft);
restoreDraft();
render();

// Narrow bridge for the Adobe Express adapter; all design state remains in the editor.
window.designXDMSneaker={getName:()=>state.name,createPNG:async()=>{const image=await renderImage();const canvas=document.createElement('canvas');canvas.width=1800;canvas.height=image.height;canvas.getContext('2d').drawImage(image,0,0,1800,image.height);const blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/png'));if(!blob)throw Error('Unable to prepare sneaker image.');return blob;}};
